<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { Capacitor } from '@capacitor/core'
import { Keyboard } from '@capacitor/keyboard'
import { ChevronRight } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import type { LedgerType } from '@/domain/models/category'
import CategoryIcon from '@/components/CategoryIcon.vue'
import { useAppStore } from '@/stores/app-store'
import { defaultCategoryIcon } from '@/ui/category-icons'
import CategoryParentPicker from './CategoryParentPicker.vue'
import CategoryIconPickerPage from './CategoryIconPickerPage.vue'
import { colorOf, softOf } from '@/domain/services/category-color'

const store = useAppStore()
const route = useRoute()
const router = useRouter()
const id = computed(() => typeof route.params.id === 'string' ? route.params.id : undefined)
const type = ref<LedgerType>(route.query.type === 'income' ? 'income' : 'expense')
const parentSelection = ref(typeof route.query.parentId === 'string' ? route.query.parentId : '')
const name = ref('')
const icon = ref(defaultCategoryIcon(type.value))
const color = ref<string>('#1677ff')
const error = ref('')
const saving = ref(false)
const parentPickerOpen = ref(false)
const iconPickerOpen = ref(false)
const nameInput = ref<HTMLInputElement>()
const editingGroup = ref(false)
let focusTimer: number | undefined

/** 颜色选择器的 14 色板：内置二级色板 12 色 + 黑 + 白（一级二级都能选） */
const COLOR_SWATCHES: readonly string[] = ['#1677ff', '#ff7a45', '#8b5cf6', '#06b6d4', '#20a162', '#ef4444', '#eab308', '#ec4899', '#0ea5e9', '#14b8a6', '#a16207', '#7c3aed', '#17233d', '#ffffff']

const parents = computed(() => store.categories.filter((category) => category.type === type.value && category.parentId === null && !category.disabled && category.id !== id.value))
const parentLabel = computed(() => {
  if (parentSelection.value === '__root__') return '创建一级分类'
  return parents.value.find((parent) => parent.id === parentSelection.value)?.name ?? '请选择'
})
const isGroup = computed(() => parentSelection.value === '__root__')

onMounted(async () => {
  await store.initialize()
  if (!store.canWrite) {
    store.notify('激活授权码后才能修改分类', 'error')
    await router.replace('/settings/license')
    return
  }
  if (id.value) {
    const category = await store.repository.getCategory(id.value)
    if (!category || category.isDefault) { store.notify('只能编辑自定义分类', 'error'); await router.replace('/settings/categories'); return }
    type.value = category.type
    editingGroup.value = category.parentId === null
    parentSelection.value = category.parentId ?? '__root__'
    name.value = category.name
    icon.value = category.icon
    color.value = colorOf(category, store.categories)
  }
  await nextTick()
  focusTimer = window.setTimeout(async () => {
    nameInput.value?.focus({ preventScroll: true })
    if (Capacitor.getPlatform() === 'android') await Keyboard.show().catch(() => undefined)
  }, 180)
})
onBeforeUnmount(() => { if (focusTimer) window.clearTimeout(focusTimer) })

function setType(value: LedgerType): void {
  if (value === type.value) return
  type.value = value
  parentSelection.value = ''
  icon.value = defaultCategoryIcon(value)
}

function selectParent(value: string): void {
  parentSelection.value = value
  parentPickerOpen.value = false
}

function selectIcon(value: string): void {
  icon.value = value
  iconPickerOpen.value = false
}

function selectColor(value: string): void {
  color.value = value
}

const currentIconStyle = computed(() => ({ background: softOf(color.value), color: color.value }))

async function save(): Promise<void> {
  error.value = ''
  const normalized = name.value.trim()
  if (!normalized) { error.value = '请输入分类名称'; return }
  if (Array.from(normalized).length > 5) { error.value = '分类名称最多 5 个字'; return }
  if (!parentSelection.value) { error.value = '请选择所属分类'; return }
  const parentId = isGroup.value ? null : parentSelection.value
  if (parentId && !parents.value.some((parent) => parent.id === parentId)) { error.value = '所选分类组不可用，请重新选择'; return }
  const duplicate = store.categories.some((category) => category.id !== id.value && category.type === type.value && category.parentId === parentId && category.name === normalized)
  if (duplicate) { error.value = '同一分类组中已经存在同名分类'; return }
  saving.value = true
  try {
    const previous = id.value ? await store.repository.getCategory(id.value) : undefined
    const now = new Date().toISOString()
    const siblings = store.categories.filter((category) => category.type === type.value && category.parentId === parentId)
    const value = {
      id: id.value ?? crypto.randomUUID(), name: normalized, icon: parentId ? icon.value : defaultCategoryIcon(type.value), type: type.value,
      parentId, isDefault: false, disabled: previous?.disabled ?? false,
      sortOrder: previous?.sortOrder ?? Math.max(-1, ...siblings.map((category) => category.sortOrder)) + 1,
      color: color.value,
      createdAt: previous?.createdAt ?? now, updatedAt: now,
    }
    if (previous && previous.parentId !== parentId) await store.repository.moveCustomCategory(value)
    else await store.repository.putCategory(value)
    await store.refresh()
    store.notify(id.value ? '分类已更新' : '分类已添加', 'success')
    await router.replace({ name: 'categories', query: { type: type.value } })
  } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存失败' }
  finally { saving.value = false }
}
</script>

<template>
  <main class="page edit-page">
    <form class="form-card" @submit.prevent="save">
      <div class="form-fields card">
        <label class="form-row">
          <span class="field-label">分类名称</span>
          <span class="name-field">
          <input ref="nameInput" v-model="name" maxlength="5" autocomplete="off" placeholder="请输入分类名称" autofocus />
          <small>{{ Array.from(name).length }}/5</small>
          </span>
        </label>

        <div v-if="!id" class="form-row type-row">
          <span id="ledger-type-label" class="field-label">收支类型</span>
          <div class="type-options" role="radiogroup" aria-labelledby="ledger-type-label">
            <label><input type="radio" name="ledger-type" value="expense" :checked="type === 'expense'" @change="setType('expense')" /><span>支出</span></label>
            <label><input type="radio" name="ledger-type" value="income" :checked="type === 'income'" @change="setType('income')" /><span>收入</span></label>
          </div>
        </div>

        <button class="form-row form-select" type="button" :class="{ locked: editingGroup }" :disabled="editingGroup" @click="parentPickerOpen = true">
          <span class="field-label">所属分类</span>
          <span :class="{ placeholder: !parentSelection }">{{ parentLabel }}</span><ChevronRight :size="21" aria-hidden="true" />
        </button>

        <button v-if="!isGroup" class="form-row form-select icon-select" type="button" @click="iconPickerOpen = true">
          <span class="field-label">分类图标</span><span class="current-icon" :style="currentIconStyle"><CategoryIcon :name="icon" :size="24" /></span><span>选择图标</span><ChevronRight :size="21" aria-hidden="true" />
        </button>

        <div class="form-row color-row">
          <span class="field-label">分类颜色</span>
          <div class="color-swatches" role="radiogroup" aria-label="分类颜色">
            <button v-for="swatch in COLOR_SWATCHES" :key="swatch" type="button" role="radio" :aria-checked="color === swatch" :class="{ selected: color === swatch }" :style="{ backgroundColor: swatch }" :aria-label="`颜色 ${swatch}`" @click="selectColor(swatch)" />
          </div>
        </div>
      </div>

      <p v-if="error" class="field-error" role="alert">{{ error }}</p>
      <button class="button primary submit" type="submit" :disabled="saving">{{ saving ? '保存中' : '保存分类' }}</button>
    </form>
  </main>

  <CategoryParentPicker :open="parentPickerOpen" :parents="parents" :selected="parentSelection" :allow-root="!id" @close="parentPickerOpen = false" @select="selectParent" />
  <CategoryIconPickerPage v-if="iconPickerOpen" :type="type" :selected="icon" @close="iconPickerOpen = false" @select="selectIcon" />
</template>

<style scoped>
.form-card { display: grid; gap: 16px; }
.form-fields { overflow: hidden; }
.form-row { display: grid; width: 100%; min-height: 68px; grid-template-columns: 88px minmax(0, 1fr); align-items: center; gap: 12px; padding: 8px 16px; border: 0; border-bottom: 1px solid var(--color-border); background: transparent; color: var(--color-text); text-align: left; }
.form-row:last-child { border-bottom: 0; }
.field-label { color: var(--color-text-secondary); font-size: 16px; }
.name-field { display: grid; min-width: 0; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; }
.name-field input { width: 100%; min-width: 0; min-height: 48px; border: 0; outline: 0; background: transparent; color: var(--color-text); text-align: right; }
.name-field small { color: var(--color-text-secondary); }
.type-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); overflow: hidden; border: 1px solid var(--color-border); border-radius: 12px; }
.type-options label { display: flex; min-height: 48px; align-items: center; gap: 8px; padding: 0 12px; }
.type-options label + label { border-left: 1px solid var(--color-border); }
.type-options input { width: 20px; height: 20px; accent-color: var(--color-primary); }
.form-select { grid-template-columns: 88px minmax(0, 1fr) auto; }
.form-select > :nth-child(2) { min-width: 0; overflow: hidden; text-align: right; text-overflow: ellipsis; white-space: nowrap; }
.placeholder { color: var(--color-text-secondary); }
.form-select.locked { cursor: default; opacity: .72; }
.icon-select { grid-template-columns: 88px 44px minmax(0, 1fr) auto; }
.icon-select > :nth-child(3) { text-align: right; }
.current-icon { display: grid; width: 42px; height: 42px; place-items: center; border-radius: 12px; }
.color-row { grid-template-columns: 88px minmax(0, 1fr); align-items: center; }
.color-swatches { display: flex; flex-wrap: wrap; gap: 10px; justify-content: flex-end; }
.color-swatches button { width: 32px; height: 32px; border: 2px solid transparent; border-radius: 50%; cursor: pointer; padding: 0; transition: transform 0.1s; }
.color-swatches button:active { transform: scale(0.9); }
.color-swatches button.selected { border-color: var(--color-primary); box-shadow: 0 0 0 2px var(--color-surface) inset; }
.submit { width: 100%; margin-top: 2px; }
</style>
