        <input type="radio" name="category-parent" value="__root__" :checked="selected === '__root__'" @change="emit('select', '__root__')" />
        <span><strong>创建一级分类</strong><small>作为新的分类组显示</small></span>
      </label>
      <label v-for="parent in parents" :key="parent.id">
        <input type="radio" name="category-parent" :value="parent.id" :checked="selected === parent.id" @change="emit('select', parent.id)" />
        <span>{{ parent.name }}</span>
      </label>
    </div>
  </AppDialog>
